  function table(headers,rows) {return `<div class="pg-table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(v=>`<td>${v ?? '—'}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">${empty('No records yet')}</td></tr>`}</tbody></table></div>`;}
