  function publicHeader() {return `<div class="pg-public-top"><span>DHANVANTRI GLOBAL PVT LTD</span><span>PRODUCTS · PARTNERS · CLEAR RECORDS</span></div><header class="pg-public-header"><a href="#home" aria-label="${COMPANY} home">${brand()}</a><button class="pg-menu" data-pg="menu" aria-label="Toggle navigation">☰</button><nav id="pg-public-nav"><a href="#home">HOME</a><a href="#catalog">PRODUCTS</a><a href="#contact">CONTACT</a><a href="#terms">TERMS</a><a href="#privacy">PRIVACY</a><a href="${S.user?'#overview':'#login'}">${S.user?'MY WORKSPACE':'MEMBER LOGIN'}</a></nav></header>`;}
  function publicFooter() {return `<footer class="pg-footer"><div>${brand()}<p>Products and a connected partner experience.</p></div><div><h3>DISCOVER</h3><a href="#home">About the company</a><a href="#catalog">Products</a><a href="#contact">Contact & enquiries</a></div><div><h3>PARTNER WORKSPACE</h3><a href="#overview">Dashboard</a><a href="#team">Binary tree</a><a href="#income">Income reports</a></div><div><h3>INFORMATION</h3><a href="#terms">Website terms</a><a href="#privacy">Privacy policy</a><p>Income depends on approved qualifying sales and the company’s approved plan. No income is guaranteed.</p></div><div class="pg-copyright">© ${new Date().getFullYear()} ${COMPANY}</div></footer>`;}
  function dropdown(label,entries) {return `<details class="pg-nav-dropdown"><summary>${label}</summary><div>${entries.map(([name,route])=>`<a href="#${route}">${name}</a>`).join('')}</div></details>`;}
  function memberHeader() {return `<header class="pg-member-header"><a href="#overview" aria-label="${COMPANY} dashboard">${brand()}</a><button class="pg-menu" data-pg="menu" aria-label="Toggle member navigation">☰</button><nav id="pg-member-nav">${dropdown('DIRECT SELLER DETAIL',[['PROFILE DETAIL','profile'],['ACCOUNT SECURITY','security']])}${dropdown('REGISTRATION & PURCHASING',[...(admin()?[['NEW REGISTRATION','admin-members']]:[]),['PURCHASE ORDER','catalog'],['PURCHASE WALLET','funding']])}${dropdown('SALE DETAILS',[['ORDER DETAIL','orders'],['INCOME REFLECTION','reflection']])}${dropdown('GENEALOGY',[['BINARY TREE','team'],['TEAM MEMBER REPORT','members']])}${dropdown('COMMISSION REPORTS',[['INCOME REPORT','income'],['CLOSING STATEMENT','statement'],['PAYOUT DETAILS','wallet']])}<a href="#benefits">REWARD & BENEFITS</a>${admin()?dropdown('MANAGEMENT',[['ADMIN CONSOLE','admin'],['MEMBERS','admin-members'],['PRODUCTS','admin-products'],['ORDER REVIEW','admin-orders'],['PROFIT & CLOSING','admin-closing'],['WALLET REVIEW','admin-funding'],['PAYOUT REVIEW','admin-withdrawals'],['BENEFIT REVIEW','admin-benefits'],['PLAN CONFIGURATION','admin-plan'],['ENQUIRIES','admin-enquiries'],['AUDIT HISTORY','audit']]):''}<button data-pg="logout">LOGOUT</button></nav></header>`;}
  function metrics(member) {return member||{left_bv:0,right_bv:0,carry_left_bv:0,carry_right_bv:0,self_bv:0,matched_bv:0};}
  function avatar(color='#158b25') {return `<svg viewBox="0 0 80 85" aria-hidden="true"><ellipse cx="40" cy="24" rx="18" ry="22" fill="${color}"/><path d="M24 45q16 15 32 0 22 12 23 35H1q1-23 23-35Z" fill="${color}"/></svg>`;}
  function tileIcon(kind) {const mapped=({member:'profile',product:'profile',wallet:'money',team:'team',report:'document',benefit:'award',security:'kyc',audit:'document',logout:'logout'})[kind]||'document';return window.PartnerReference?.art?`<span class="pg-tile-symbol" aria-hidden="true">${window.PartnerReference.art(mapped)}</span>`:`<span class="pg-tile-symbol" aria-hidden="true">◇</span>`;}
  function stat(label,value,color='blue',route='income') {return `<a href="#${route}" class="pg-summary ${color}"><strong>${value}</strong><span>${label}</span>${avatar('#184a65')}</a>`;}
  function actionTile(label,value,color,route,kind) {return `<a class="pg-action ${color}" href="#${route}">${tileIcon(kind)}<span>${label}${value!==''?`<strong>${value}</strong>`:''}</span></a>`;}
  function overview() {
    const owner=self(),v=metrics(owner),sum=S.data.summary||{},left=members().filter(m=>m.parent_id===owner?.id&&m.side==='left').length,right=members().filter(m=>m.parent_id===owner?.id&&m.side==='right').length;
    const p=[['MEMBER ID',owner?.id||'ADMINISTRATOR'],['JOINING DATE',owner?.joined_at?date(owner.joined_at):'—'],['ACCOUNT ROLE',S.user.role.toUpperCase()],['DIRECT LEFT / RIGHT',`${left} / ${right}`],['LEFT BV',num(v.left_bv)],['RIGHT BV',num(v.right_bv)],['SELF BV',num(v.self_bv)],['MATCHED BV',num(v.matched_bv)],['LEFT CARRY',num(v.carry_left_bv)],['RIGHT CARRY',num(v.carry_right_bv)],['PURCHASE WALLET',money(sum.purchase_balance_paise)]];
    const pending=(S.data.orders||[]).filter(o=>/pending/i.test(o.status)).length+(S.data.withdrawals||[]).filter(o=>/pending/i.test(o.status)).length+(S.data.fundingRequests||[]).filter(o=>/pending/i.test(o.status)).length;
    return `<div class="pg-dashboard"><aside class="pg-profile"><div class="pg-profile-avatar">${avatar('#b1b9bc')}</div><h1>${esc(owner?.name||S.user.name)}</h1><p>ID NO. ${esc(owner?.id||S.user.username)}</p><dl>${p.map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl>${button('Profile detail','go','data-route="profile"','light')}</aside><div class="pg-dashboard-main"><div class="pg-summary-grid">${stat('TOTAL INCOME',money(sum.total_income_paise),'blue')}${stat('AVAILABLE EARNINGS',money(sum.available_paise),'blue','wallet')}${stat('PAYOUT RESERVED',money(sum.reserved_paise),'red','wallet')}${stat('LEFT BUSINESS VOLUME',num(v.left_bv),'orange','team')}${stat('RIGHT BUSINESS VOLUME',num(v.right_bv),'orange','team')}${stat('PLAN STATUS',S.data.plan.approved?'ACTIVE':'PENDING APPROVAL','orange',admin()?'admin-plan':'benefits')}</div><section class="pg-action-board"><div class="pg-action-grid">${[
      ...(admin()?[['SIGN UP','','cyan','admin-members','member']]:[['MY PROFILE','','cyan','profile','member']]),['PURCHASE ORDER','','cyan','catalog','product'],['ORDER DETAIL','','cyan','orders','product'],['WALLET FUND REQUEST','','cyan','funding','wallet'],['PURCHASE WALLET',money(sum.purchase_balance_paise),'brick','funding','wallet'],['PROFILE DETAILS','','gray','profile','member'],['ACCOUNT SECURITY','','teal','security','security'],['DIRECT SELLER TEAM',num(left+right),'navy','members','team'],['DOWNLINE TEAM',num(Math.max(0,members().length-(owner?1:0))),'lime','members','team'],['BINARY TREE',`${num(v.left_bv)} || ${num(v.right_bv)}`,'pink','team','team'],['TOTAL INCOME',money(sum.total_income_paise),'purple','income','team'],['MATCHING STATEMENT','','pink','statement','report'],['INCOME REFLECTION','','pink','reflection','report'],['BENEFIT REQUESTS',num((S.data.benefits||[]).length),'pink','benefits','benefit'],['FUNDING RECORDS','','pink','funding','report'],['PAYOUT DETAILS',money(sum.paid_paise),'pink','wallet','wallet'],['EDUCATION SUPPORT','','navy','benefits','benefit'],['MONTHLY BENEFIT','','blue','benefits','benefit'],['COMPANY INFORMATION','','lime','terms','report'],...(admin()?[['ADMIN APPROVALS',num(pending),'red','admin','audit']]:[['CONTACT SUPPORT','','red','contact','report']])].map(v=>actionTile(...v)).join('')}</div></section>${note()}</div></div>`;
  }
  function productCard(p) {return `<article class="pg-product"><div class="pg-product-image">${tileIcon('product')}<span>${esc(p.name)}</span></div><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p><div><strong>${money(p.price_paise)}</strong><span>${num(p.bv)} BV</span></div>${button(S.user?'Create purchase order':'Sign in to order',S.user?'order-form':'go',S.user?`data-id="${esc(p.id)}"`:'data-route="login"')}</article>`;}
  function catalog() {return `${pageTitle('Our products','Published product information and current company pricing.')}<div class="pg-product-grid">${products().length?products().map(productCard).join(''):empty('Products are being prepared','The company has not published its product catalogue yet. Please contact the team for availability.')}</div>`;}
  function home() {return `<section class="pg-hero"><img src="living-hero.jpg" alt="Everyday home and personal care essentials"><div><span>DHANVANTRI GLOBAL</span><h1>Everyday essentials.<br>Connected possibilities.</h1><h2>Products for familiar routines.</h2><p>Explore our products and a partner workspace that keeps orders, business volume and earnings clearly recorded.</p><a class="pg-button" href="#catalog">VIEW PRODUCTS →</a></div><div class="pg-hero-features"><span>✓ PRODUCT FOCUS</span><span>✓ CLEAR SALES RECORDS</span><span>✓ CONNECTED PARTNER WORKSPACE</span></div></section><section class="pg-public-section"><div class="pg-section-title"><h2>OUR PRODUCT RANGE</h2><p>Explore the company’s published collection.</p></div><div class="pg-product-grid">${products().slice(0,4).map(productCard).join('')||empty('The collection is being prepared','Contact the company for product availability and current information.')}</div></section><section class="pg-public-section pg-story"><div class="pg-story-art">${brand()}<strong>Products.<br>People.<br>Progress.</strong></div><div><h2>A connected approach.</h2><p>${COMPANY} brings product orders and partner records together in one place. Members can view their Left and Right team, approved business volume and recorded earnings.</p><p>Qualifying product sales and the approved company plan determine commission. Membership or placement by itself does not produce income.</p><a class="pg-button" href="#contact">CONTACT THE COMPANY</a></div></section><section class="pg-public-cta"><h2>Your team. Your progress. Clearly recorded.</h2><a class="pg-button light" href="${S.user?'#overview':'#login'}">OPEN MEMBER WORKSPACE →</a></section><section class="pg-public-section"><div class="pg-section-title"><h2>A CLEAR PROCESS</h2></div><div class="pg-process-grid">${[['01','Explore products','View published product information, prices and business volume.'],['02','Place an order','Use your funded purchase wallet; the company verifies each order.'],['03','Follow your team','See approved product volume in your Left and Right network.'],['04','Review earnings','View the recorded closing, available balance and payout status.']].map(([n,t,c])=>`<article><span>${n}</span><h3>${t}</h3><p>${c}</p></article>`).join('')}</div></section>`;}
  function login() {return `<div class="pg-login"><div><span>MEMBER & ADMIN ACCESS</span><h1>Welcome to<br>Dhanvantri Global.</h1><p>Use the account issued by the company. Your role determines the information and actions available in your workspace.</p></div><section class="pg-panel"><h2>Sign in</h2><form data-form="login">${field('User ID','username','text','','required maxlength="100" autocomplete="username"')}${field('Password','password','password','','required autocomplete="current-password"')}<p class="pg-form-error" role="alert"></p><button class="pg-button" type="submit">Sign in securely</button><p class="pg-form-note">For account recovery, contact the company through its verified support channel. Never send your password with an enquiry.</p></form></section></div>`;}
  function contact() {return `${pageTitle('Contact & enquiries','Send a product, account or company enquiry. Do not include passwords, bank details or government identification.')}<div class="pg-form-column">${panel('How can we help?',`<form data-form="enquiry">${field('Your name','name','text','','required maxlength="100" autocomplete="name"')}${field('Email','email','email','','required maxlength="200" autocomplete="email"')}${field('Phone (optional)','phone','tel','','maxlength="20" autocomplete="tel"')}<label class="pg-field">Your enquiry<textarea name="message" rows="5" required minlength="10" maxlength="3000"></textarea></label><p class="pg-form-note">Your information will be used to respond to this enquiry. <a href="#privacy">Read privacy information.</a></p><p class="pg-form-error" role="alert"></p><button class="pg-button" type="submit">Send enquiry</button></form>`)}</div>`;}
  function legal(kind) {return `${pageTitle(kind==='privacy'?'Privacy information':'Website terms','Draft company information — final business terms and company contact details must be approved before commercial launch.')}<article class="pg-panel pg-prose">${kind==='privacy'?`<h2>Who operates this service</h2><p>This website is prepared for ${COMPANY}. The company’s registered address, privacy contact, retention schedule and grievance contact have not yet been supplied for publication.</p><h2>Information used</h2><p>The service records account identity, member placement, phone details, orders, funding references, earnings, requests and audit events. Enquiry details are used to respond to your message. Passwords are stored as salted hashes. Access is limited by account permissions; private member contact details are not exposed in public pages.</p><h2>Your choices</h2><p>You can update your own phone number and password in your workspace. For access, correction or deletion requests, use the company’s verified support channel or submit a contact enquiry. Financial records may need retention under the company’s approved policy and applicable requirements.</p><h2>Browser storage</h2><p>A session cookie maintains sign-in. The service does not store account passwords or financial records in browser local storage. No advertising or analytics integration is enabled by this application.</p>`:`<h2>Products and accounts</h2><p>Published products, prices and business volume are managed by the company. Orders are reviewed after the company verifies payment and fulfilment eligibility. A purchase-wallet funding request does not constitute an online payment; an administrator must verify the external payment reference before crediting funds.</p><h2>Partner plan</h2><p>Joining or adding a member does not generate income. Earnings require qualifying product sales, an approved compensation plan, available company funding and a recorded closing. No income, return or rank is guaranteed. The company must approve the plan and issue its full direct-selling agreement, return/refund policy and required disclosures before commercial launch.</p><h2>Payouts and benefits</h2><p>Payout approval records an internal review. A payout is marked paid only after the company records an external transfer reference. The application does not itself transfer bank funds. Education support is a request and review workflow, not approval or disbursal of a loan. The monthly benefit requires eligibility review and available approved funding.</p><h2>Pending company documents</h2><p>Registered address, CIN/GST details if applicable, customer-care and grievance contacts, shipping/returns/refunds, eligibility rules, cancellation periods and final contractual documents have not been supplied. These draft website terms must not be treated as the company’s final contract.</p>`}<a class="pg-button light" href="#contact">Contact the company</a></article>`;}
  function team() {
    const root=members().find(m=>m.id===S.focus)||self()||members()[0];
    if(!root)return pageTitle('Binary tree')+panel('Team structure',empty('No members registered','An administrator can register the first root member and its Left / Right team.'));
    const positions=[],links=[];function visit(n,parent,side,depth,lo,hi){const p={n,parent,side,depth,x:(lo+hi)/2,y:depth*170+15};positions.push(p);if(parent)links.push([parent,p]);if(!n||depth===2)return;for(const s of ['left','right'])visit(members().find(m=>m.parent_id===n.id&&m.side===s),p,s,depth+1,s==='left'?lo:p.x,s==='left'?p.x:hi);}
    visit(root,null,null,0,0,1000);const v=metrics(root),parent=members().find(m=>m.id===root.parent_id);
    return `${pageTitle('BINARY TREE','Click a person to open their branch. Click a member ID for the information you are permitted to view.')}<section class="pg-panel pg-tree-panel"><div class="pg-tree-toolbar"><form data-form="tree-search"><label for="pg-tree-search">User ID / name</label><input id="pg-tree-search" name="query" type="search" value="${esc(S.query)}" required><button class="pg-button">Show</button></form><div>${parent?button('↑ Parent','tree-focus',`data-id="${esc(parent.id)}"`,'light'):''}${button('Root','tree-root','','light')}</div></div><div class="pg-tree-totals"><strong>Left BV : ${num(v.left_bv)}</strong><span>${esc(root.name)} · ${esc(root.id)}</span><strong>Right BV : ${num(v.right_bv)}</strong></div><div class="pg-tree-scroll"><div class="pg-tree-canvas"><svg class="pg-tree-lines" viewBox="0 0 1000 500" aria-hidden="true">${links.map(([a,b])=>`<path d="M${a.x} ${a.y+102}V${b.y-28}H${b.x}V${b.y}"/>`).join('')}</svg>${positions.map(({n,parent,side,x,y})=>`<div class="pg-tree-node" style="left:${x}px;top:${y}px">${n?`<button class="pg-tree-person" data-pg="tree-focus" data-id="${esc(n.id)}" aria-label="Open ${esc(n.name)} branch">${avatar(n.self_bv>0?'#0b890a':'#d2b027')}</button><button class="pg-tree-id" data-pg="member-detail" data-id="${esc(n.id)}">${esc(n.id)}</button><span>${esc(n.name)}</span>`:`<div class="pg-tree-vacant">${avatar('#94c1d6')}</div>${admin()?button(`Add ${side}`,'member-form',`data-parent="${esc(parent.n.id)}" data-side="${side}"`,'light'):'<span>Open position</span>'}`}</div>`).join('')}</div></div><div class="pg-tree-legend"><span>● Green: approved self business volume</span><span>● Yellow: no self business volume</span><span>● Blue: open position</span></div><div class="pg-tree-volumes">${[['SELF BV',v.self_bv],['LEFT CARRY',v.carry_left_bv],['RIGHT CARRY',v.carry_right_bv],['MATCHED BV',v.matched_bv]].map(([k,val])=>`<div><small>${k}</small><strong>${num(val)}</strong></div>`).join('')}</div></section>`;
  }
  function memberTable() {return table(['Member ID','Name','Phone','Placement parent','Side','Joined','Business volume'],members().filter(m=>!S.query||`${m.id} ${m.name}`.toLowerCase().includes(S.query.toLowerCase())).map(m=>[`<button class="pg-link" data-pg="member-detail" data-id="${esc(m.id)}">${esc(m.id)}</button>`,esc(m.name),esc(m.phone||'Private'),esc(m.parent_id||'Root'),esc(m.side||'—'),date(m.joined_at),`${num(m.left_bv)} / ${num(m.right_bv)} BV`]));}
  function memberReport() {return pageTitle('Team member report','Your permitted team placements and approved business volume.',admin()?button('Register member','member-form'):'')+panel('Registered members',`<form data-form="member-search" class="pg-search"><label for="pg-member-search">Find member</label><input id="pg-member-search" name="query" value="${esc(S.query)}" placeholder="ID or name"><button class="pg-button">Search</button>${button('Clear','member-search-clear','','light')}</form>${memberTable()}`);}
  const filteredLedger=()=> (S.data.ledger||[]).filter(r=>(S.route==='reflection'||r.account==='commission')&&(S.route!=='statement'||r.kind==='matching_credit')&&(S.ledgerType==='all'||r.type===S.ledgerType||r.kind===S.ledgerType)&&(!S.ledgerMonth||String(r.created_at||r.date||'').startsWith(S.ledgerMonth))&&(!admin()||S.ledgerMember==='all'||r.member_id===S.ledgerMember));
