  function income() {const rows=(S.data.ledger||[]).filter(r=>(S.route==='reflection'||r.account==='commission')&&(S.route!=='statement'||r.kind==='matching_credit')),types=[...new Set(rows.map(r=>r.type||r.kind).filter(Boolean))];return pageTitle(heading[S.route],S.route==='reflection'?'Purchase and commission movements are shown separately by account; every movement comes from the server ledger.':S.route==='statement'?'Matching closing credits and their original source references. No TDS or fee is deducted by this version.':'Commission account entries only. Purchase-wallet funding is not commission income.',button('Export CSV','export-ledger','','light'))+panel('Ledger entries',`<form data-form="ledger-filter" class="pg-filter">${admin()?select('Member','member',options([['all','All members'],...members().map(m=>[m.id,`${m.id} · ${m.name}`])],S.ledgerMember)):''}${select('Entry type','type',options([['all','All entries'],...types.map(t=>[t,t])],S.ledgerType))}${field('Month','month','month',S.ledgerMonth)}<button class="pg-button">Apply</button></form>${ledgerTable(filteredLedger())}`);}
  function wallet() {const s=S.data.summary||{};return pageTitle('Earnings & wallet','Requests reserve the available balance. Bank transfers are performed externally by the company.',S.user.member_id?button('Request payout','withdrawal-form'):'')+`<div class="pg-small-stats">${stat('AVAILABLE',money(s.available_paise),'blue','wallet')}${stat('RESERVED',money(s.reserved_paise),'orange','wallet')}${stat('PAID',money(s.paid_paise),'blue','wallet')}</div>`+panel('Payout requests',table(['Reference','Created','Amount','Status','External reference'],(S.data.withdrawals||[]).map(r=>[esc(r.id),date(r.created_at),money(r.amount_paise),badge(r.status),esc(r.reference||r.payment_reference||'—')])));}
  function funding() {const s=S.data.summary||{};return pageTitle('Purchase wallet','Submit only references for payments you have already made through the company’s verified external payment instructions.',S.user.member_id?button('Submit funding request','funding-form'):'')+`<div class="pg-small-stats">${stat('PURCHASE BALANCE',money(s.purchase_balance_paise),'blue','funding')}</div>`+panel('Funding requests',table(['Reference','Created','Amount','Payment reference','Status'],(S.data.fundingRequests||[]).map(r=>[esc(r.id),date(r.created_at),money(r.amount_paise),esc(r.reference||'—'),badge(r.status)])));}
  function orders() {return pageTitle('Order & dispatch detail','Orders use your funded purchase wallet. BV is recognised only after company approval.',S.user.member_id?'<a href="#catalog" class="pg-button">View products</a>':'')+panel('Orders',table(['Order','Created','Product','Quantity','Total','BV','Status','Reference'],(S.data.orders||[]).map(r=>[esc(r.id),date(r.created_at),esc(r.product_name||r.product_id),num(r.quantity),money(r.total_paise||r.amount_paise),num(r.total_bv||r.bv),badge(r.status),esc(r.reference||'—')])));}
  function benefits() {return pageTitle('Benefit requests','The company reviews eligibility. Education review is not a loan approval or disbursal.',S.user.member_id?button('New benefit request','benefit-form'):'')+note()+panel('Request history',table(['Reference','Created','Type','Period','Status','Note'],(S.data.benefits||[]).map(r=>[esc(r.id),date(r.created_at),esc(r.type),esc(r.period),badge(r.status),esc(r.note||r.reason||'—')])));}
  function profile() {const m=members().find(m=>m.id===S.user.member_id);return pageTitle('Member profile')+`<div class="pg-two-column">${panel('Account information',`<dl class="pg-details"><div><dt>Name</dt><dd>${esc(S.user.name)}</dd></div><div><dt>User ID</dt><dd>${esc(S.user.username)}</dd></div><div><dt>Role</dt><dd>${esc(S.user.role)}</dd></div><div><dt>Member ID</dt><dd>${esc(S.user.member_id||'Administrator')}</dd></div><div><dt>Placement</dt><dd>${esc(m?.parent_id||(m?'Root':'Not applicable'))} ${esc(m?.side||'')}</dd></div></dl>`)}${m?panel('Update your phone',`<form data-form="profile">${field('Phone','phone','tel',m.phone||'','required maxlength="20" autocomplete="tel"')}<p class="pg-form-error" role="alert"></p><button class="pg-button">Save phone number</button></form>`):panel('Administration','<p>The administrator account has no member placement. Register members through the admin console.</p>')}</div>`;}
  function security() {return pageTitle('Account security',S.user.force_password_change?'Choose a new password before continuing to your account.':'Use a unique password of at least 12 characters.')+`<div class="pg-form-column">${panel('Change password',`<form data-form="password">${field('Current password','current_password','password','','required autocomplete="current-password"')}${field('New password','new_password','password','','required minlength="12" maxlength="128" autocomplete="new-password"')}${field('Confirm new password','confirm_password','password','','required minlength="12" maxlength="128" autocomplete="new-password"')}<p class="pg-form-error" role="alert"></p><button class="pg-button">Change password</button></form>`)}</div>`;}
  function adminHome() {return pageTitle('Admin console','Manage company records, verify external references and review server-recorded activity.')+`<div class="pg-admin-grid">${[['Members','Register accounts and place members in the Left / Right network.','admin-members'],['Products','Publish product names, prices and approved business volume.','admin-products'],['Orders','Verify orders before recognising business volume.','admin-orders'],['Profit & closing','Record realised profit and close funded matching income.','admin-closing'],['Purchase wallet','Review external payment references and wallet funding.','admin-funding'],['Payouts','Review reserved earnings and record external transfer references.','admin-withdrawals'],['Benefits','Review eligibility for education or monthly requests.','admin-benefits'],['Plan configuration','Record an approved compensation plan and its reference.','admin-plan'],['Enquiries','Respond to product and account enquiries.','admin-enquiries'],['Audit history','Review the append-only record of administrative changes.','audit']].map(([t,c,r])=>`<a href="#${r}" class="pg-panel"><h2>${t}</h2><p>${c}</p><span>OPEN →</span></a>`).join('')}</div>`;}
  function adminMembers() {return pageTitle('Member registration','Register the root member first, then place each member below its correct parent.',`<div class="pg-row-actions">${button('Import verified records','import-form','','light')}${button('Register member','member-form')}</div>`)+panel('Registered members',memberTable())+panel('Member access','<p>Imported member accounts have no password and remain disabled until an administrator issues a temporary password securely. The member must then change it on first sign-in.</p>'+button('Issue temporary password','credentials-form','','light'));}
